                "센터마다 실제 반 편성과 수업 시간은 다를 수 있으므로 상담 시점에 직접 확인해야 합니다. 답변 옆에는 학생의 현재 자료와 맞는 점, 추가로 확인할 점을 구분해 적어 보세요.",
