                "상담에서 들은 설명은 진단 자료, 수업 중 질문, 과제 회수, 오답 재확인의 순서로 나누어 적어 보세요. 학생의 생활 일정 안에서 실행 가능한지도 별도 기준으로 확인해야 합니다.",
                "수업 내용이 학생에게 맞는지와 실제로 꾸준히 다닐 수 있는지는 따로 확인하는 편이 좋습니다. 교재와 시간표, 비용, 반 편성은 상담에서 최신 정보를 확인하세요.",
