                "상담 답변이 구체적인지는 담당자 이름보다 확인 자료와 다음 행동이 분명한지로 살펴볼 수 있습니다. 수업 운영 정보는 방문 또는 전화 상담에서 최신 내용을 확인해야 합니다.",
                "한 번의 답변으로 결정하기보다 학생의 현재 진도, 가능한 요일, 가정 복습 시간을 함께 놓고 비교하세요. 아직 확인하지 못한 항목은 빈칸으로 남겨 다음 상담 질문으로 이어가는 편이 좋습니다.",
