                f"틀린 문제는 해설을 읽고 끝내지 말고 {local} 학생이 핵심 어휘와 문장 구조를 설명할 수 있는지 확인합니다. 며칠 뒤 같은 유형의 지문을 스스로 읽는 과정까지 이어 보세요.",
