                "상담 기록에는 이번 시험에서 고쳐야 할 문제와 다음 달에도 다시 볼 개념을 서로 다른 칸에 적어 보세요. 당장의 범위와 누적 복습을 분리하면 짧은 시험 준비 때문에 이전 오답 확인이 계속 밀리는지를 구체적으로 살필 수 있습니다.",
